        elif json_str[0] == '[':
            return parse_array(json_str)
        elif json_str[0] == '"':
            return parse_string(json_str)
        elif json_str[0].isdigit() or json_str[0] == '-':
            return parse_number(json_str)
        elif json_str == 'true':
            return True
        elif json_str == 'false':
            return False
        elif json_str == 'null':
            return None
        else:
            raise ValueError('Invalid JSON')

