        if json_str[0] != '{':
            raise ValueError('Invalid JSON')
        json_str = json_str[1:]
        obj = {}
        while json_str[0] != '}':
            key = parse_string(json_str)
            json_str = json_str[len(key) + 2:]
            value = parse_value(json_str)
            json_str = json_str[len(str(value)) + 1:]
            obj[key] = value
        return obj

    def parse_array(json_str):
        if json_str[0] != '[':
